package main

import (
	"fmt"
	"sort"
)

func main() {
	m := map[string]int{"b": 2, "a": 1, "c": 3}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys) // impose deterministic order
	for _, k := range keys {
		fmt.Println(k, m[k])
	}
	// Output:
	// a 1
	// b 2
	// c 3
}

