package main

import (
	"fmt"
	"sync"
)

func main() {
	var mu sync.Mutex
	m := map[string]int{}
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			mu.Lock()
			m["count"]++ // guarded write
			mu.Unlock()
		}()
	}
	wg.Wait()
	fmt.Println(m["count"])
	// Output: 100
}

