package solution

import (
	"sort"
	"strconv"
)

func WordCount(words []string) []string {
	counts := make(map[string]int, len(words)) // pre-size to reduce rehashing
	for _, w := range words {
		counts[w]++ // zero value 0 makes ++ work on first sight
	}

	keys := make([]string, 0, len(counts)) // collect keys for ordering
	for k := range counts {
		keys = append(keys, k)
	}
	sort.Strings(keys) // deterministic output

	out := make([]string, 0, len(keys))
	for _, k := range keys {
		out = append(out, k+":"+strconv.Itoa(counts[k]))
	}
	return out
}

