import "sort"

func Keys(m map[string]int) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out) // deterministic order
	return out
}

func FrequencySort[T comparable](items []T) []T {
	counts := make(map[T]int, len(items)) // frequency per distinct item
	order := make([]T, 0, len(items))     // first-appearance order
	for _, it := range items {
		if _, seen := counts[it]; !seen {
			order = append(order, it) // record first sighting
		}
		counts[it]++
	}
	sort.SliceStable(order, func(i, j int) bool {
		return counts[order[i]] > counts[order[j]] // desc frequency; stable keeps first-seen ties
	})
	return order
}

type Counter struct {
	mu sync.RWMutex
	m  map[string]int
}

func NewCounter() *Counter {
	return &Counter{m: make(map[string]int)} // init map -> no nil-write panic
}

func (c *Counter) Inc(key string) {
	c.mu.Lock()        // exclusive: structural write
	c.m[key]++
	c.mu.Unlock()
}

func (c *Counter) Value(key string) int {
	c.mu.RLock()       // shared: concurrent reads allowed
	defer c.mu.RUnlock()
	return c.m[key]    // returns 0 for absent keys
}
